/**
 * PURE — what kind of change each file of a pull request is (#64), so a
 * review can show the parts that need thought first and fold the mechanical
 * ones away. No agent: rules over the path and the changed lines, which are
 * data (`DEFAULT_RULES` for .NET and Node, plus config `reviews.rules` before
 * them). Shared with the SPA and the demo; keep it import-free.
 *
 * A file's kind, in this order (the first that applies):
 *   1. marked generated by `.gitattributes` (linguist-generated), or a
 *      generated-kind rule's path;
 *   2. mechanical: a pure rename, a whitespace-only change (not where
 *      indentation is meaning: Python, YAML, Makefiles…), or only
 *      using / import lines changed;
 *   3. the first other rule whose path matches;
 *   4. the first rule whose content pattern matches a changed line;
 *   5. logic.
 * Each answer says why (`why`), and by what (`by`): a rule, or what git said.
 */

export type ChangeKind = 'schema' | 'api' | 'logic' | 'wiring' | 'dependencies' | 'tests' | 'mechanical' | 'generated';

/** The review's order: the parts that need thought first, the folded ones last. */
export const KIND_ORDER: ChangeKind[] = ['schema', 'api', 'logic', 'wiring', 'dependencies', 'tests', 'mechanical', 'generated'];

/** Shown folded, with a count: nothing to think about there. */
export const FOLDED_KINDS: ReadonlySet<ChangeKind> = new Set(['mechanical', 'generated']);

export const KIND_LABEL: Record<ChangeKind, string> = {
  schema: 'Schema',
  api: 'API surface',
  logic: 'Logic',
  wiring: 'Wiring',
  dependencies: 'Dependencies, build & CI',
  tests: 'Tests',
  mechanical: 'Mechanical',
  generated: 'Generated',
};

export interface KindRule {
  kind: ChangeKind;
  /** What the rule is, as a file's reason says it ("EF Core migration designer"). */
  name: string;
  /** Path globs (forward slashes; `**`, `*`, `?`, `{a,b}`); a pattern with no `/` matches the file name anywhere. */
  paths?: string[];
  /** Regexes (source) matched against the file's changed lines: one match puts the file here. */
  content?: string[];
}

