/** A using / import line: one that only brings names in. */
const IMPORT_LINE = [
  /^\s*using\s+(static\s+)?[\w.]+(\s*=\s*[\w.<>]+)?\s*;\s*$/,
  /^\s*global\s+using\s+[\w.]+\s*;\s*$/,
  /^\s*import\s/,
  /^\s*export\s+(\*|\{[^}]*\}|type\s+\{[^}]*\})\s+from\s+['"][^'"]+['"];?\s*$/,
  /^\s*from\s+[\w.]+\s+import\s/,
  /^\s*#include\s/,
  /^\s*(const|let|var)\s+[\w{},\s]+=\s*require\(['"][^'"]+['"]\);?\s*$/,
  /^\s*[\w,{}\s]+\}?\s*from\s+['"][^'"]+['"];?\s*$/, // the tail of a multi-line import
];

/** A file of the PR, as the classifier reads it. */
export interface ChangedFile {
  path: string;
  oldPath?: string;
  status: 'added' | 'deleted' | 'modified' | 'renamed' | 'binary';
  added: number;
  deleted: number;
  /** The changed lines' text (added and deleted), without the +/- prefix. */
  changed: string[];
  /** `.gitattributes` marks it linguist-generated. */
  generated?: boolean;
  /** git's whitespace-ignoring diff has nothing for it. */
  whitespaceOnly?: boolean;
}

export interface FileKind {
  path: string;
  kind: ChangeKind;
  /** Why it's in this group, in a few words ("EF Core migration designer", "pure rename"). */
  why: string;
  /** What decided it: a rule, or what git said about the file. */
  by: 'rule' | 'git';
}

const globCache = new Map<string, RegExp>();

/** A glob as a regex over a forward-slash path. A pattern with no `/` matches the file name in any folder. */
export function globToRegExp(glob: string): RegExp {
  const hit = globCache.get(glob);
  if (hit) return hit;
  const anywhere = !glob.includes('/');
  let re = '';
  for (let i = 0; i < glob.length; i++) {
    const c = glob[i];
    if (c === '*') {
      if (glob[i + 1] === '*') {
        // `**/` = any folders (none too); `**` at the end = anything.
        if (glob[i + 2] === '/') {
          re += '(?:.*/)?';
          i += 2;
        } else {
          re += '.*';
          i += 1;
        }
      } else re += '[^/]*';
    } else if (c === '?') re += '[^/]';
    else if (c === '{') {
      const end = glob.indexOf('}', i);
      if (end < 0) re += '\\{';
      else {
        re += `(?:${glob
          .slice(i + 1, end)
          .split(',')
          .map((p) => p.replace(/[.+^$()|[\]\\]/g, '\\$&').replace(/\*/g, '[^/]*'))
          .join('|')})`;
        i = end;
      }
    } else re += c.replace(/[.+^$()|[\]\\]/g, '\\$&');
  }
  const out = new RegExp(`^${anywhere ? '(?:.*/)?' : ''}${re}$`, 'i');
  globCache.set(glob, out);
  return out;
}

/**
 * Files a review leaves out altogether — not listed, not diffed, not given to the AI step, not counted against the
 * size limit — only named, with how many lines, on the overview: a designer file (`*.Designer.cs`: an EF migration's
 * is thousands of lines of model snapshot, a form's or a resource's is the tool's own) is never read (reported). Pure.
 */
export const IGNORED_IN_REVIEW: ReadonlyArray<{ name: string; paths: string[] }> = [{ name: 'designer file', paths: ['*.Designer.cs'] }];

/** Why a review leaves this file out (the rule's name), or null when it reads it. */
export function ignoredInReview(path: string): string | null {
  return IGNORED_IN_REVIEW.find((r) => r.paths.some((g) => globToRegExp(g).test(path)))?.name ?? null;
}

const pathMatches = (rule: KindRule, path: string) => (rule.paths ?? []).some((g) => globToRegExp(g).test(path));

function contentMatches(rule: KindRule, lines: string[]): boolean {
  for (const src of rule.content ?? []) {
    let re: RegExp;
    try {
      re = new RegExp(src);
    } catch {
      continue; // a bad pattern from config matches nothing
    }
    if (lines.some((l) => re.test(l))) return true;
  }
  return false;
}

/** Only using / import lines changed (blank lines aside), and at least one. */
export function importsOnly(lines: string[]): boolean {
  const meaningful = lines.filter((l) => l.trim() !== '');
  return meaningful.length > 0 && meaningful.every((l) => IMPORT_LINE.some((re) => re.test(l)));
}

/**
 * Files whose indentation is meaning (Python, YAML, Makefiles' tabs, F#, Haskell, Pug, Sass…): a whitespace-only
 * change there can change what it does, so it is never folded away as mechanical.
 */
const WHITESPACE_MATTERS =
  /(^|\/)(GNUmakefile|[Mm]akefile)$|\.(py|pyi|pyw|pyx|ya?ml|mk|make|fs|fsi|fsx|hs|lhs|elm|nim|coffee|pug|jade|haml|slim|sass|styl)$/i;

/** A change of whitespace alone can change what this file does. */
export const whitespaceMatters = (path: string): boolean => WHITESPACE_MATTERS.test(path);

/** A file's kind and why. `rules`: config's first, then the defaults (`rulesWith`). */
export function classifyFile(f: ChangedFile, rules: KindRule[] = DEFAULT_RULES): FileKind {
  const base = { path: f.path };
  if (f.generated) return { ...base, kind: 'generated', why: 'marked generated in .gitattributes', by: 'git' };
  const generated = rules.find((r) => r.kind === 'generated' && pathMatches(r, f.path));
  if (generated) return { ...base, kind: 'generated', why: generated.name, by: 'rule' };
  if (f.status === 'renamed' && f.added === 0 && f.deleted === 0)
    return { ...base, kind: 'mechanical', why: `pure rename from ${f.oldPath ?? 'another path'}`, by: 'git' };
  if (f.whitespaceOnly && (f.added > 0 || f.deleted > 0) && !whitespaceMatters(f.path))
    return { ...base, kind: 'mechanical', why: 'whitespace only', by: 'git' };
  if (f.status !== 'added' && f.status !== 'deleted' && importsOnly(f.changed))
    return { ...base, kind: 'mechanical', why: 'only using / import lines changed', by: 'rule' };
  const byPath = rules.find((r) => r.kind !== 'generated' && pathMatches(r, f.path));
  if (byPath) return { ...base, kind: byPath.kind, why: byPath.name, by: 'rule' };
  const byContent = rules.find((r) => contentMatches(r, f.changed));
  if (byContent) return { ...base, kind: byContent.kind, why: byContent.name, by: 'rule' };
  return { ...base, kind: 'logic', why: 'no rule matched: hand-written code', by: 'rule' };
}

const KINDS = new Set<string>(KIND_ORDER);

/** Config `reviews.rules`, checked (anything malformed is left out), before the defaults. */
export function rulesWith(configured: unknown): KindRule[] {
  const mine = Array.isArray(configured)
    ? configured.filter(
        (r): r is KindRule =>
          !!r &&
          typeof r === 'object' &&
          KINDS.has((r as KindRule).kind) &&
          typeof (r as KindRule).name === 'string' &&
          (Array.isArray((r as KindRule).paths) || Array.isArray((r as KindRule).content)) &&
          ((r as KindRule).paths ?? []).every((p) => typeof p === 'string') &&
          ((r as KindRule).content ?? []).every((p) => typeof p === 'string'),
      )
    : [];
  return [...mine, ...DEFAULT_RULES];
}

/** Files grouped by kind, in the review's order (empty groups left out). */
export function groupByKind<T extends { kind: ChangeKind }>(files: T[]): Array<{ kind: ChangeKind; files: T[] }> {
  return KIND_ORDER.map((kind) => ({ kind, files: files.filter((f) => f.kind === kind) })).filter((g) => g.files.length > 0);
}
